  auto table=new QTableWidget(0,5);table->setObjectName("goalRoutes");table->setHorizontalHeaderLabels({tr("이름 / ID"),tr("목표 엔딩 / 사건"),tr("명령 수"),tr("검사 결과"),tr("실패 위치 · 원인")});table->setSelectionBehavior(QAbstractItemView::SelectRows);table->setSelectionMode(QAbstractItemView::SingleSelection);table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);table->horizontalHeader()->setSectionResizeMode(4,QHeaderView::Stretch);table->setMinimumHeight(150);box->addWidget(table,1);
  auto navigation=new QHBoxLayout;box->insertLayout(2,navigation);
