  auto save=new QPushButton(tr("목표 경로 저장"));save->setObjectName("goalSave");box->addWidget(save);auto summary=new QLabel(tr("기록 파일을 읽거나 등록된 경로를 선택하세요."));summary->setObjectName("goalSummary");summary->setWordWrap(true);box->addWidget(summary);auto detail=new QPlainTextEdit;detail->setObjectName("goalDetails");detail->setReadOnly(true);detail->setMaximumHeight(120);box->addWidget(detail);
